const lv_image_dsc_t *fisix_icon_get(const char *app)
{
    int i;
    static const struct { const char *app; const lv_image_dsc_t *dsc; } tab[] = {
        { "TERMINAL", &fisix_icon_terminal },
        { "FILES", &fisix_icon_files },
        { "NANO", &fisix_icon_nano },
        { "CALCULATOR", &fisix_icon_calculator },
        { "GAMES", &fisix_icon_games },
        { "PONG", &fisix_icon_pong },
        { "MINESWEEPER", &fisix_icon_minesweeper },
        { "SNAKE", &fisix_icon_snake },
        { "BROWSY", &fisix_icon_browsy },
        { "RETERM", &fisix_icon_reterm },
        { "Z", &fisix_icon_z },
        { "PATHIFY", &fisix_icon_pathify },
        { "SETTINGS", &fisix_icon_settings },
        { "SHUTDOWN", &fisix_icon_shutdown },
        { "CLIPONG", &fisix_icon_clipong },
        { "NOTEPAD", &fisix_icon_notepad },
        { "CLOCK", &fisix_icon_clock },
        { "MS-DOS", &fisix_icon_ms_dos },
        { "PAINT", &fisix_icon_paint },
        { "ALL APPS", &fisix_icon_all_apps },
    };
    if (!app) return 0;
    for (i = 0; i < (int)(sizeof(tab) / sizeof(tab[0])); i++) {
        const char *a = app, *b = tab[i].app;
        while (*a && *b && *a == *b) { a++; b++; }
        if (*a == 0 && *b == 0) return tab[i].dsc;
    }
    return 0;
}

